const list = $input.all().map(item => item.json);
console.log(list)
let blocks = [];

for (const item of list) {
  if(item.qtdErrors > 0){
    console.log(item)
    blocks.push({
			"type": "section",
			"text": {
				"type": "mrkdwn",
				"text": `:aviso: *${item.workflowName}*\n *${item.qtdErrors}* errors found in the last run`
			},
			"accessory": {
				"type": "button",
				"text": {
					"type": "plain_text",
					"text": "Vizualize",
					"emoji": true
				},
				"value": "click_me_123",
				"url": `${item.url}`,
				"action_id": "button-action"
			}
		})
  }
}

if(blocks.length > 0){
  return {
    blocks: blocks
  };
}else{
  return null
}

const list = $("Aggregate").last().json.data;

const lastHour = new Date();
lastHour.setHours(lastHour.getHours() - 1);


const executionsLastHour = list.filter(execution => {
  const dataStoppedAt = new Date(execution.stoppedAt);

  return dataStoppedAt > lastHour;
});

if (executionsLastHour.length > 0) {
  console.log(`Foram encontrados ${executionsLastHour.length} itens da última hora.`);
} else {
  console.log("Nenhum item da última hora foi encontrado.");
}

return {
  workflowId: $("Loop").last().json.id,
  workflowName: $("Loop").last().json.name,
  qtdErrors: executionsLastHour.length,
  url: $("Config").last().json.urlBase + $("Loop").last().json.id
}
